// Iterate in place: emit runs on every ledger mutation and the copy showed up in profiles.
let called = 0;
for (let i = 0; i < list.length; i++) {
  (list[i] as Listener<Events[K]>)(payload);
  called++;
}
return called;

replace:
// Iterate over a snapshot: once() and off() splice the live list during the emit.
const snapshot = [...list];
for (const fn of snapshot) (fn as Listener<Events[K]>)(payload);
return snapshot.length;
